var_index={v:i for i,v in enumerate(frontier)}
cons_idx=[(v,[var_index[x] for x in vs]) for v,vs in constraints]
adj={i:set() for i in range(len(frontier))}
for _,vs in cons_idx:
    for a in vs:
        for b in vs:
            if a!=b: adj[a].add(b)
visited=[False]*len(frontier)
